import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"34、【大壯】 乾下震上","description":"子夏易傳 - 34、【大壯】 乾下震上","frontmatter":{"title":"34、【大壯】 乾下震上","description":"子夏易傳 - 34、【大壯】 乾下震上"},"headers":[],"relativePath":"classics/zixia/036.md","filePath":"classics/zixia/036.md"}'),i={name:"classics/zixia/036.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_34、【大壯】-乾下震上" tabindex="-1">34、【大壯】 乾下震上 <a class="header-anchor" href="#_34、【大壯】-乾下震上" aria-label="Permalink to “34、【大壯】 乾下震上”">​</a></h1><p>卦辭：大壯，利貞。</p><p>彖曰：大壯，大者壯也。剛以動，故壯大。壯，利貞，大者正也。正大而天地之情可見矣。</p><p>子夏：陽剛也，大也，剛而不邪，大而能周，時而後動，故大者壯，而得其正也。天地以正，大而得其生。聖人以正，大而天下化。其道剛動而大者正也。</p><p>象曰：雷在天上，大壯。君子以非禮弗履。</p><p>子夏：雷在天上，陽氣大行，君子得其道也。非禮弗履，保其壯也。</p><p>初九，壯於趾，徵兇，有孚。</p><p>象曰：壯於趾，其孚窮也。</p><p>子夏：剛以處下，不有其大，初而遂用其壯也。壯在乎趾，何以用哉，以之而徵，兇其冝也，故信有窮也。</p><p>九二，貞吉。</p><p>象曰：九二貞吉，以中也。</p><p>子夏：守正處卑，得中之道，全其壯也。故貞吉矣。</p><p>九三，小人用壯，君子用罔。貞厲，羝羊觸藩，羸其角。</p><p>象曰：小人用壯，君子罔也。</p><p>子夏：剛居上而得位也。小人知進不知退，故用其壯也。壯必見傷，正之危也。四剛在上，將陵過之，能容無忌，必羸闐矣。君子逹於幾危，故不用也。</p><p>九四，貞吉悔亡，藩決不羸，壯於大輿之輹。</p><p>象曰：藩決不羸，尚往也。</p><p>子夏：為剛長之首升於上，體守於臣位，志在除邪，疑其逼也。故貞吉乃悔亡矣。往皆柔也，物無逆之，藩決而不羸也。居大臣之任，可以載其剛之用也。</p><p>六五，喪羊於易，無悔。</p><p>象曰：喪羊於易，位不當也。</p><p>子夏：剛長也。而以柔乘之五陽也。而以陰處之，雖欲用壯，是喪其壯，而不難也。質柔而不可恃也。柔不終拒尊中獲存故無悔也。</p><p>上六，羝羊觸藩，不能退，不能遂，無攸利，艱則吉。</p><p>象曰：不能退，不能遂，不詳也。艱則吉，咎不長也。</p><p>子夏：柔居壯，極非其壯，而用壯也。將觸藩矣。恃應而往，不能退也。質弱道窮，不能遂也。進退無可安所之哉，若自守其柔，艱以為志，不敢盈殆，得其吉矣。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
